// 1️⃣ Cargar fixture con info del PO
cy.fixture('po').then(poData => {
  // 2️⃣ Login & flujo de creación
  _login.default.login(Cypress.env('USER'), Cypress.env('PASS'));
  _purchaseOrder.default.purchaseOrder(); // <- esto ejecuta completePo() y guarda @codigoOC
  // 3️⃣ Esperar a que completePo guarde el código
  cy.get('@codigoOC').then(codigoOC => {
    // 4️⃣ Leer JSON guardado (doble seguridad)
    cy.readFile('cypress/fixtures/datos-guardados.json').then(({
      codigoOC: codigoJson
    }) => {
      const codigo = codigoOC || codigoJson;
      const fecha = new Date().toLocaleString();
      const {
        proveedor,
        unidadNegocio,
        ubicacionEnvio,
        comprador,
        articulos
      } = poData.purchaseOrder;
      const articulosHtml = articulos.map((item, index) => `
      <tr>
        <td style="padding:4px 8px;border:1px solid #ccc;">${index + 1}</td>
        <td style="padding:4px 8px;border:1px solid #ccc;">${item.codigoArticulo}</td>
        <td style="padding:4px 8px;border:1px solid #ccc;">${item.cantidad}</td>
        <td style="padding:4px 8px;border:1px solid #ccc;">${item.price}</td>
      </tr>
    `).join("");
      const html = `
      <div style="background:#eef;padding:12px;border-radius:8px;font-size:13px;">
        <b>📦 Orden Generada:</b> ${codigo}<br><br>
        <b>Proveedor:</b> ${proveedor}<br>
        <b>Unidad Negocio:</b> ${unidadNegocio}<br>
        <b>Ubicación Envío:</b> ${ubicacionEnvio}<br>
        <b>Comprador:</b> ${comprador}<br><br>
        <b>🛒 Artículos:</b><br><br>
        <table style="border-collapse:collapse;font-size:12px;">
          <tr style="background:#ddd;">
            <th style="padding:4px 8px;border:1px solid #ccc;">#</th>
            <th style="padding:4px 8px;border:1px solid #ccc;">Código</th>
            <th style="padding:4px 8px;border:1px solid #ccc;">Cantidad</th>
            <th style="padding:4px 8px;border:1px solid #ccc;">Precio</th>
          </tr>
          ${articulosHtml}
        </table><br>
        <b>👤 Usuario:</b> ${Cypress.env("USER")}<br>
        <b>📅 Fecha:</b> ${fecha}
      </div>
    `;
      // 5️⃣ Enviar bloque HTML al reporte Mochawesome
      cy.task('mochawesome:addContext', {
        test: Cypress.currentTest.title,
        value: html
      });
      cy.log(`✅ Orden registrada en reporte: ${codigo}`);
    });
  });
});

// Esperar 2 minutos
